// Evaluate in the preview browser. No backend or external assets required.
async () => {
  const assert = (ok, message) => { if (!ok) throw Error(message); };
  const wait = () => new Promise(resolve => setTimeout(resolve, 150));
  const click = async (text, root = document) => {
    const button = [...root.querySelectorAll("button")].find(b => b.textContent.trim() === text);
    assert(button, "Missing button: " + text);
    button.focus(); button.click(); await wait();
  };
  const nav = async name => {
    const button = [...document.querySelectorAll(".nav-item")].find(b => b.firstChild.textContent === name);
    assert(button, "Missing navigation: " + name); button.click(); await wait();
  };
  const query = async value => {
    const input = document.querySelector(".query-input");
    input.value = value; input.dispatchEvent(new Event("input", { bubbles: true })); await wait();
  };
  assert(document.querySelector("h1").textContent === "Cluster", "Cluster is not the default page");
  assert(![...document.querySelectorAll(".nav-item")].some(b => b.firstChild.textContent === "Overview"), "Overview navigation remains");
  await click("Replay"); await click("Pause");
  assert(!document.querySelector(".detail-tabs"), "Cluster still has join-request tabs");
  const clusterTitles = [...document.querySelectorAll("#page h2")].map(e => e.textContent);
  assert(clusterTitles.includes("Active tasks") && clusterTitles.includes("Discovery"), "Cluster sections missing");
  assert(!clusterTitles.some(t => /control plane|attention|join requests/i.test(t)), "Removed sections remain");
  const discovery = () => [...document.querySelectorAll(".table-panel")].find(p => p.querySelector("h2").textContent === "Discovery");
  assert(document.querySelector(".tables .table-panel") === discovery(), "Discovery is not first");
  const initialDiscovered = [...discovery().querySelectorAll("tbody tr")];
  assert(initialDiscovered.slice(0,2).every(r => r.children[2].textContent === "Awaiting approval"), "Requesting hosts not first");
  assert(initialDiscovered[2].querySelector("button").textContent === "Add", "Other discoveries missing Add");
  assert(initialDiscovered[0].children[2].querySelector(".status-label") && initialDiscovered[0].children[2].classList.contains("tone-warning"), "Awaiting approval is not yellow");
  assert(initialDiscovered[0].querySelector(".button-success").textContent === "Approve" && initialDiscovered[0].querySelector(".button-danger").textContent === "Reject", "Approval colors/actions missing");
  await click("Reject", discovery().querySelector('[data-resource="maple"]'));
  await click("Simulate rejection", document.querySelector("dialog"));
  assert(discovery().querySelector("tbody tr").dataset.resource === "willow", "Remaining join request did not stay at top");
  assert(discovery().querySelector('[data-resource="maple"]').children[1].textContent === "unjoined", "Reject enrolled a host");
  await click("Approve", discovery().querySelector('[data-resource="willow"]'));
  await click("Simulate approval", document.querySelector("dialog"));
  assert(!discovery().querySelector('[data-resource="willow"]'), "Approved host remained in Discovery");
  await click("Add", discovery().querySelector('[data-resource="spruce"]'));
  await click("Simulate add", document.querySelector("dialog"));
  assert(!discovery().querySelector('[data-resource="spruce"]'), "Added host remained in Discovery");
  const enrolled = [...document.querySelectorAll(".table-panel")].find(p => p.querySelector("h2").textContent === "Cluster hosts");
  assert(enrolled.querySelector('[data-resource="willow"]').children[2].classList.contains("tone-warning"), "Pending membership is not yellow");
  await click("Add", discovery().querySelector('[data-resource="maple"]'));
  await click("Simulate add", document.querySelector("dialog"));
  assert(!discovery(), "Empty Discovery section remains visible");
  assert(getComputedStyle(document.querySelector("#workspace")).getPropertyValue("--accent").trim() === "#e57000", "Default theme is not Proxmox orange");
  document.querySelectorAll(".host-shortcut")[1].click(); await wait();
  assert(document.querySelector("h1").textContent === "birch", "Host shortcut failed");
  const info = document.querySelector(".identity-panel"), metrics = document.querySelector(".telemetry"), history = document.querySelector(".table-panel");
  assert(info.compareDocumentPosition(metrics) & Node.DOCUMENT_POSITION_FOLLOWING, "Telemetry is not below host information");
  assert(metrics.compareDocumentPosition(history) & Node.DOCUMENT_POSITION_FOLLOWING, "History is not below telemetry");
  assert(document.querySelectorAll(".metric").length === 4 && document.querySelectorAll("svg.metric-chart").length === 3, "Telemetry is missing");
  assert(document.querySelector("svg.metric-chart").getBoundingClientRect().height <= 36, "Telemetry graphs not compact");
  const shutdown = [...document.querySelectorAll(".header-actions button")].find(b => b.textContent === "Shutdown…");
  assert(shutdown.classList.contains("button-danger"), "Shutdown is not a destructive header action");
  assert(getComputedStyle(shutdown).borderRadius === "0px", "Curved browser controls remain");
  const count = document.querySelectorAll(".table-panel tbody tr").length;
  await click("Network check");
  assert(document.querySelectorAll(".table-panel tbody tr").length === count + 1, "Network check did not appear in history");
  await click("Shutdown…");
  assert(document.querySelector("dialog").open && document.activeElement.id === "dialog-cancel", "Unsafe review default");
  await click("Cancel", document.querySelector("dialog"));
  assert(!document.querySelector("dialog").open && document.activeElement === shutdown, "Modal focus was not restored");
  await click("Shutdown…"); await click("Simulate shutdown", document.querySelector("dialog"));
  assert(document.querySelector("h1").textContent === "Shutdown", "Confirmation did not open task");
  await click("Result");
  assert(document.querySelector("#page").textContent.includes("not been observed"), "Uncertain power effect mislabeled");
  await nav("Hosts"); await query("birch");
  assert(document.querySelectorAll("tbody tr").length === 1, "Host search did not filter");
  await query(""); document.querySelectorAll(".host-shortcut")[2].click(); await wait();
  assert([...document.querySelectorAll(".header-actions button")].find(b => b.textContent === "Shutdown…").disabled, "Offline power action enabled");
  assert([...document.querySelectorAll(".metric-value")].every(e => e.textContent === "—"), "Offline telemetry fabricated");
  await nav("Tasks"); await click("Active");
  assert([...document.querySelectorAll("tbody tr")].every(e => /running|reconciling/.test(e.children[1].textContent)), "Active filter wrong");
  await click("All"); await query("failed");
  assert(document.querySelectorAll("tbody tr").length === 1, "Task search did not filter state");
  await query("");
  document.querySelector('[data-resource="network-birch"]').click(); await wait(); await click("Logs");
  const log = document.querySelector("#task-log");
  log.style.height = "38px"; log.scrollTop = 0; log.dispatchEvent(new Event("scroll")); await wait();
  assert(document.querySelector(".log-panel button").textContent.includes("Follow paused"), "Scroll did not pause follow");
  await click("Follow paused · Jump to latest");
  assert(log.scrollTop + log.clientHeight >= log.scrollHeight - 2, "Follow did not reach tail");
  await nav("Settings");
  assert(!document.querySelector(".detail-tabs"), "Settings still has tabs");
  const panels=[...document.querySelectorAll("#page .section-grid > section")].map(e=>e.getBoundingClientRect());
  assert(panels.every((r,i)=>!i || (Math.abs(r.left-panels[0].left)<1 && r.top>=panels[i-1].bottom)), "Settings is not a single column");
  const settingsTitles=[...document.querySelectorAll("#page h2")].map(e=>e.textContent);
  assert(settingsTitles.includes("Current connection") && settingsTitles.includes("Effective configuration") && settingsTitles.includes("Theme"), "Settings sections not visible together");
  const oldTheme = document.querySelector("#workspace").dataset.theme;
  await click("Theme · " + oldTheme);
  assert(document.querySelector("#workspace").dataset.theme !== oldTheme, "Theme did not change");
  await click("Accent color"); await click("Reduced motion");
  assert(document.querySelector("#workspace").dataset.reduced === "true", "Reduced motion unavailable");
  while(document.querySelector("#workspace").dataset.theme!=="Graphite") await click("Theme");
  for(let i=0;i<4 && getComputedStyle(document.querySelector("#workspace")).getPropertyValue("--accent").trim()!=="#e57000";i++) await click("Accent color");
  await nav("Cluster");
  return { passed: true, horizontalOverflow: document.documentElement.scrollWidth > innerWidth };
}
